INSERT INTO `r26_practicum_course_files` (`id`, `batch_subject_id`, `syllabus_pdf_path`, `program`, `course_title`, `course_code`, `semester`, `type_of_course`, `teaching_scheme`, `contact_hours`, `credits`, `cie_marks`, `ese_marks`, `parsed_cos`, `parsed_modules`, `parsed_experiments`, `parsed_copo`, `parsed_textbooks`, `self_learning_configs`, `created_at`, `updated_at`, `doc_checklist`) VALUES ('2', '37', NULL, 'Engineering', 'Basic Mechanical Engineering', 'ME-1021', '1', 'Practicum', '3:0:3:0', '90', '4.5', '40', '100', '[{\"id\":\"CO1\",\"description\":\"Demonstrate basic concepts, electrical quantities, signal types, and electronic measuring instruments.\",\"cognitive_level\":\"Apply\"},{\"id\":\"CO2\",\"description\":\"Construct and analyze basic electronic circuits using passive electronic components.\",\"cognitive_level\":\"Apply\"},{\"id\":\"CO3\",\"description\":\"Apply semiconductor theory to demonstrate the operation of semiconductor devices.\",\"cognitive_level\":\"Apply\"},{\"id\":\"CO4\",\"description\":\"Demonstrate Printed Circuit Boards and apply soldering techniques.\",\"cognitive_level\":\"Apply\"}]', '[{\"module_id\":\"I\",\"title\":\"Introduction to Electronics, Signals and Measurements\",\"content\":\"Introduction, applications, electrical quantities, signals, lab familiarization\",\"hours\":11},{\"module_id\":\"II\",\"title\":\"Passive Electronic Components\",\"content\":\"Resistors, capacitors, inductors, transformers, series\\/parallel testing\",\"hours\":12},{\"module_id\":\"III\",\"title\":\"Active Electronic Components\",\"content\":\"Semiconductor theory, PN junction diode, Zener diode, LED, photodiode\",\"hours\":12},{\"module_id\":\"IV\",\"title\":\"PCB and Soldering\",\"content\":\"PCB types, layout design, fabrication steps, soldering practice\",\"hours\":10}]', '[{\"experiment_no\":\"EXP-01\",\"title\":\"Familiarization of electronics labs and measuring instruments\",\"co_id\":\"CO1\",\"hours\":3},{\"experiment_no\":\"EXP-02\",\"